61	#define SOX_INT_MIN(bits) (1 << ((bits) - 1) == 0 ? INT_MIN : \
62	                           -(1 << ((bits) - 1)))
63	#define SOX_INT_MAX(bits) (int)(((unsigned)-1) >> (33 - (bits)))
64	#define SOX_UINT_MAX(bits) (int)(SOX_INT_MIN(bits) ^ SOX_INT_MAX(bits))
65	
66	#define SOX_INT_TO_SAMPLE(d, bits) ((sox_sample_t)(d) << (32 - (bits)))
67	#define SOX_UINT_TO_SAMPLE(d, bits) \
68	    ((sox_sample_t)((((unsigned)(d)) ^ (unsigned)SOX_INT_MIN(bits)) << (32 - (bits))))
69	
70	/* Round-to-nearest with saturation towards SOX_INT_MAX. */
71	#define SOX_SAMPLE_TO_SIGNED(bits, d, clips) \
72	    (int32_t)( \
73	      lsx_macro_temp_sample = (d), \
74	      lsx_macro_temp_sample > (sox_sample_t)(SOX_SAMPLE_MAX - (1 << (31 - (bits)))) ? \
75	        ++(clips), SOX_INT_MAX(bits) : \
76	        ((uint32_t)(lsx_macro_temp_sample + (1 << (31 - (bits))))) >> (32 - (bits)))
77	
78	#define SOX_SAMPLE_TO_UNSIGNED(bits, d, clips) \
79	    (uint32_t)(SOX_SAMPLE_TO_SIGNED(bits, d, clips) ^ SOX_INT_MIN(bits))
80	
81	#define SOX_SIGNED_8BIT_TO_SAMPLE(d, c)   SOX_INT_TO_SAMPLE(d, 8)
82	#define SOX_UNSIGNED_8BIT_TO_SAMPLE(d, c) SOX_UINT_TO_SAMPLE(d, 8)
83	#define SOX_SIGNED_16BIT_TO_SAMPLE(d, c)  SOX_INT_TO_SAMPLE(d, 16)
84	#define SOX_UNSIGNED_16BIT_TO_SAMPLE(d, c) SOX_UINT_TO_SAMPLE(d, 16)
85	#define SOX_SIGNED_24BIT_TO_SAMPLE(d, c)  SOX_INT_TO_SAMPLE(d, 24)
86	#define SOX_UNSIGNED_24BIT_TO_SAMPLE(d, c) SOX_UINT_TO_SAMPLE(d, 24)
87	#define SOX_SIGNED_32BIT_TO_SAMPLE(d, c)  ((sox_sample_t)(d))
88	#define SOX_UNSIGNED_32BIT_TO_SAMPLE(d, c) \
