93	#define SOX_SAMPLE_TO_SIGNED_16BIT(d, c)   (int16_t)SOX_SAMPLE_TO_SIGNED(16, d, c)
94	#define SOX_SAMPLE_TO_UNSIGNED_16BIT(d, c) (uint16_t)SOX_SAMPLE_TO_UNSIGNED(16, d, c)
95	#define SOX_SAMPLE_TO_SIGNED_24BIT(d, c)   (int32_t)SOX_SAMPLE_TO_SIGNED(24, d, c)
96	#define SOX_SAMPLE_TO_UNSIGNED_24BIT(d, c) (uint32_t)SOX_SAMPLE_TO_UNSIGNED(24, d, c)
97	#define SOX_SAMPLE_TO_SIGNED_32BIT(d, c)   ((int32_t)(d))
98	#define SOX_SAMPLE_TO_UNSIGNED_32BIT(d, c) \
99	    (uint32_t)((d) ^ (sox_sample_t)SOX_SAMPLE_MIN)
100	
101	/* Floating point <-> sample.  Full-scale is +/- 1.0 mapped onto 2^31. */
102	#define SOX_FLOAT_32BIT_TO_SAMPLE(d, clips) \
103	    (sox_sample_t)(LSX_UNUSED_VAR(lsx_macro_temp_sample), \
104	      lsx_macro_temp_double = (d) * (SOX_SAMPLE_MAX + 1.0), \
105	      lsx_macro_temp_double < SOX_SAMPLE_MIN * 1.0 ? \
106	        ++(clips), SOX_SAMPLE_MIN : \
107	      lsx_macro_temp_double >= SOX_SAMPLE_MAX + 1.0 ? \
108	        lsx_macro_temp_double > SOX_SAMPLE_MAX + 1.0 ? \
109	          ++(clips), SOX_SAMPLE_MAX : SOX_SAMPLE_MAX : \
110	        (sox_sample_t)lsx_macro_temp_double)
111	#define SOX_FLOAT_64BIT_TO_SAMPLE(d, clips) SOX_FLOAT_32BIT_TO_SAMPLE(d, clips)
112	
113	#define SOX_SAMPLE_TO_FLOAT_32BIT(d, clips) \
114	    (float)(LSX_UNUSED_VAR(lsx_macro_temp_double), \
115	      lsx_macro_temp_sample = (d), \
116	      lsx_macro_temp_sample > SOX_SAMPLE_MAX - 64 ? \
117	        ++(clips), (SOX_SAMPLE_MAX - 64) * (1.0 / (SOX_SAMPLE_MAX + 1.0)) : \
118	        lsx_macro_temp_sample * (1.0 / (SOX_SAMPLE_MAX + 1.0)))
119	#define SOX_SAMPLE_TO_FLOAT_64BIT(d, clips) \
120	    ((double)(d) * (1.0 / (SOX_SAMPLE_MAX + 1.0)))
121	
122	#define SOX_SAMPLE_CLIP_COUNT(samp, clips) do { \
123	    if ((samp) > SOX_SAMPLE_MAX) { (samp) = SOX_SAMPLE_MAX; ++(clips); } \
124	    else if ((samp) < SOX_SAMPLE_MIN) { (samp) = SOX_SAMPLE_MIN; ++(clips); } \
125	  } while (0)
126	
127	#define SOX_ROUND_CLIP_COUNT(d, clips) \
128	    ((d) < 0 ? (d) <= SOX_SAMPLE_MIN - 0.5 ? ++(clips), SOX_SAMPLE_MIN \
129	                                           : (d) - 0.5 \
130	             : (d) >= SOX_SAMPLE_MAX + 0.5 ? ++(clips), SOX_SAMPLE_MAX \
131	                                           : (d) + 0.5)
132	
133	#define SOX_INTEGER_CLIP_COUNT(type, d, clips) \
134	    ((d) < 0 ? (d) <= type##_MIN ? ++(clips), type##_MIN : (d) \
135	             : (d) >= type##_MAX ? ++(clips), type##_MAX : (d))
136	#define SOX_16BIT_CLIP_COUNT(d, clips) SOX_INTEGER_CLIP_COUNT(INT16, d, clips)
137	#define SOX_24BIT_CLIP_COUNT(d, clips) \
138	    ((d) < 0 ? (d) <= -8388609 ? ++(clips), -8388608 : (d) \
139	             : (d) >= 8388608 ? ++(clips), 8388607 : (d))
